template<typename T>
void sink(T&& arg) {
    // T&& is a Universal Reference (forwarding ref)
    forward_to_consumer(std::forward<T>(arg));
}

struct Consumer {
    void operator()(const int& l) {} // Lvalue path
    void operator()(int&& r) {}      // Rvalue path
};

void forward_to_consumer(int&& r) { Consumer{}(std::move(r)); }
void forward_to_consumer(const int& l) { Consumer{}(l); }

int x = 10;
sink(x);  // T deduced as int& (Lvalue) -> std::forward<int&>
sink(50); // T deduced as int (Rvalue) -> std::forward<int>
// Value category is preserved
